//! Cross-check against the cross-language oracle,
//! `testdata/vectors/normalised-queries.json` (798 cases, generated by lane C from
//! upstream RxDB in Node).
//!
//! # Why the comparison is shape-level, and exactly how much it proves
//!
//! The vectors record **normalised** queries: after defaulting, after `_deleted`
//! injection, after sort completion with the primary key. The query builder is
//! upstream's *pre*-normalisation surface — it emits `{age: {$gt: 4}}` and
//! `sort: [{name: 'asc'}]` and knows nothing about `_deleted`. So a byte comparison
//! is impossible and would be the wrong assertion to write.
//!
//! What is checkable, and is checked here:
//!
//! 1. Every `sort` shape in the corpus is expressible through the builder's three
//!    `sort()` forms, and produces the same `(field, direction)` sequence. This is
//!    the type-level contract with `dxdb_storage::MangoQuery`, which is the
//!    same type the normaliser fills, so the two cannot disagree about sort.
//! 2. `skip`/`limit` round-trip through the builder, except the documented
//!    falsy-zero divergence: upstream's builder copies `skip`/`limit` only when
//!    truthy (`nosql-query-builder.ts:50-55`), while the corpus contains queries
//!    that *normalised to* `skip: 0` / `limit: 0`.
//! 3. Every selector in the corpus is a plain object, which is the precondition
//!    `QueryBuilder::new` enforces; a corpus case with an array or scalar selector
//!    would be a builder input the port cannot represent, and the test says so
//!    instead of silently skipping.
//!
//! Every case in the corpus is exercised. A case that cannot be built is a failure,
//! not a skip: the point of the cross-check is to find the shapes the builder
//! cannot express.

use dxdb_plugin_query_builder::{QueryBuilder, SortArg, SortDirection, SortPart};
use serde_json::{json, Value};

const VECTORS: &str = "../../../testdata/vectors/normalised-queries.json";

fn load_vectors() -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(VECTORS);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|error| {
        panic!(
            "cannot read the oracle at {}: {error}\n\
             The vectors are lane C's artefact; run `make vectors` if it is missing.",
            path.display()
        )
    });
    serde_json::from_str(&text).expect("the oracle is valid JSON")
}

/// The `(field, direction)` pairs a corpus `normalizedQuery.sort` carries.
fn vector_sort(normalized: &Value) -> Vec<(String, SortDirection)> {
    let Some(parts) = normalized.get("sort").and_then(Value::as_array) else {
        return Vec::new();
    };
    parts
        .iter()
        .flat_map(|part| {
            part.as_object()
                .unwrap_or_else(|| panic!("sort part is not an object: {part}"))
                .iter()
        })
        .map(|(field, direction)| {
            let direction = direction
                .as_str()
                .unwrap_or_else(|| panic!("sort direction is not a string in {normalized}"));
            (
                field.clone(),
                SortDirection::parse(direction)
                    .unwrap_or_else(|| panic!("unknown sort direction {direction}")),
            )
        })
        .collect()
}

/// The builder's own answer for the same query, using only the builder's API.
fn builder_sort(query: &Value) -> Vec<(String, SortDirection)> {
    let mut builder = QueryBuilder::empty();
    if let Some(parts) = query.get("sort").and_then(Value::as_array) {
        // The corpus writes Mango's array-of-single-key-objects form, which is the
        // `SortArg::Object` path after flattening.
        for part in parts {
            let map = part.as_object().expect("sort part is an object");
            for (field, direction) in map {
                builder
                    .sort(SortArg::Object(vec![(field.clone(), direction.clone())]))
                    .expect("the corpus only contains valid directions");
            }
        }
    }
    builder
        .to_json()
        .expect("to_json")
        .query
        .sort
        .into_iter()
        .map(|SortPart { field, direction }| (field, direction))
        .collect()
}

#[test]
fn every_vector_sort_is_expressible_through_the_builder() {
    let vectors = load_vectors();
    let cases = vectors["cases"].as_array().expect("cases array");
    let mut with_sort = 0;
    let mut expected_failures = 0;
    for case in cases {
        let query = &case["query"];
        if query.get("sort").is_none() {
            continue;
        }
        with_sort += 1;

        // The corpus records 38 cases as expected *upstream* failures
        // (`expectedUpstreamFailure: true`, with the thrown message in `rejected`,
        // all on the `compoundIndexNoString` schema). Those have no
        // `normalizedQuery`, so there is nothing to compare a sort against. What is
        // still checkable is that the builder — which runs before normalisation —
        // accepts the query rather than tripping on the same input.
        if case.get("normalizedQuery").is_none() {
            assert_eq!(
                case["expectedUpstreamFailure"],
                json!(true),
                "case {:?} has no normalizedQuery but is not marked as an expected \
                 failure; the corpus format changed and this test is now blind",
                case["why"]
            );
            let built = builder_sort(query);
            assert_eq!(
                built.len(),
                query["sort"].as_array().map(|a| a.len()).unwrap_or(0),
                "case {:?}: builder lost a sort part",
                case["why"]
            );
            expected_failures += 1;
            continue;
        }

        let normalized = &case["normalizedQuery"];
        // The builder's round-trip of the user's sort must equal the sort the
        // normaliser ended up with *for the user-supplied parts*. Normalisation may
        // append the primary key, so compare the prefix and require the norm's part
        // count to be at least the user's.
        let from_builder = builder_sort(query);
        let from_vector = vector_sort(normalized);
        assert!(
            from_vector.starts_with(&from_builder),
            "case {:?} (schema {}): builder sort {from_builder:?} is not a prefix of the \
             normalised sort {from_vector:?}",
            case["why"],
            case["schema"]
        );
        // And the prefix must be produced by the same output type, so the storage
        // ABI sees identical data either way.
        assert_eq!(
            from_builder.len(),
            query["sort"].as_array().map(|a| a.len()).unwrap_or(0),
            "case {:?}: builder lost a sort part",
            case["why"]
        );
    }
    // 114 sort cases in the file at generation time: 109 normalising, 5 rejected by
    // the normaliser before it can emit a sort.
    assert_eq!(with_sort, 114, "the corpus's sort-case count changed");
    assert_eq!(
        expected_failures, 5,
        "the corpus's rejected-sort-case count changed"
    );
}

#[test]
fn every_vector_selector_is_a_plain_object_the_builder_accepts() {
    let vectors = load_vectors();
    let cases = vectors["cases"].as_array().expect("cases array");
    let mut checked = 0;
    for case in cases {
        let Some(selector) = case["query"].get("selector") else {
            continue;
        };
        // The precondition `QueryBuilder::new` enforces. If a corpus case violated
        // it, the builder would have input it cannot represent, which is a finding.
        assert!(
            selector.is_object(),
            "case {:?}: selector is not an object: {selector}",
            case["why"]
        );
        let mut builder = QueryBuilder::empty();
        builder.find(selector).expect("merge the user's selector");
        // Merging an object must never lose or retype a key: the resulting selector
        // has to be a superset at top level with identical values, because the
        // builder's merge never overwrites an existing key (mquery-utils.ts:21).
        let built = builder.selector();
        let built = built.as_object().expect("selector stays an object");
        for (key, value) in selector.as_object().expect("checked above") {
            assert_eq!(
                built.get(key),
                Some(value),
                "case {:?}: field {key} changed during the builder round-trip",
                case["why"]
            );
        }
        checked += 1;
    }
    assert_eq!(
        checked, 779,
        "the corpus has 779 selectors; the file changed"
    );
}

#[test]
fn skip_and_limit_round_trip_except_the_documented_falsy_zero() {
    let vectors = load_vectors();
    let cases = vectors["cases"].as_array().expect("cases array");
    let mut exact = 0;
    let mut falsy_zero = 0;
    for case in cases {
        let query = &case["query"];
        let skip = query
            .get("skip")
            .and_then(Value::as_u64)
            .map(|n| n as usize);
        let limit = query
            .get("limit")
            .and_then(Value::as_u64)
            .map(|n| n as usize);
        if skip.is_none() && limit.is_none() {
            continue;
        }
        let mut builder = QueryBuilder::empty();
        if let Some(skip) = skip {
            builder.skip(skip);
        }
        if let Some(limit) = limit {
            builder.limit(limit);
        }
        let json = builder.to_json().expect("to_json");
        if skip.unwrap_or(0) == 0 {
            // `nosql-query-builder.ts:50-55`: `if (mangoQuery.skip)` is false for 0,
            // so a `skip: 0` round-trips to the default `0` and nothing is lost.
            assert_eq!(json.query.skip, 0);
            falsy_zero += 1;
        } else {
            assert_eq!(json.query.skip, skip.expect("non-zero skip"));
            exact += 1;
        }
        if let Some(limit) = limit {
            if limit == 0 {
                // The interesting one: upstream's builder would *not* copy a
                // `limit: 0` off an existing query (`:50`), so a rebuilt query loses
                // the limit. Setting it explicitly does keep it (`:400` emits any
                // number), so the builder and the normaliser agree here.
                falsy_zero += 1;
            } else {
                exact += 1;
            }
            assert_eq!(json.query.limit, Some(limit));
        }
    }
    assert!(exact > 0, "expected some exact skip/limit round-trips");
    assert!(
        falsy_zero > 0,
        "expected the corpus to include falsy-zero cases; it did at generation time"
    );
}

#[test]
fn the_oracle_is_the_one_the_plan_names() {
    // Cheap provenance guard: the file records the upstream commit it was generated
    // from, and the lane brief pins that commit. If the vector generator ever runs
    // against a different RxDB, the cross-check above stops meaning anything.
    let vectors = load_vectors();
    let commit = vectors["rxdbCommit"]
        .as_str()
        .expect("rxdbCommit is recorded in the oracle");
    assert!(
        commit.starts_with("3b763ee17"),
        "vectors were generated from RxDB {commit}, but this lane ports 3b763ee17"
    );
}
